Ext._define('edocs.protocolo.ProtocolReferenceDetailWindow', {
    extend: 'Ext.Window',

    width: 900,

    getFormPanel: function(cfg) {
        if(!this._formPanel)
            this._formPanel = Ext._create('Ext.form.FormPanel', {
                border: false,
                frame: true,
                items: [
                    this.getProtocolTilePanel()
                ]
            });

        return this._formPanel;
    },

    getProtocolTilePanel: function(cfg) {
        if(!this.protocolTilePanel)
            this.protocolTilePanel = Ext._create('core.TilePagePanel', {
                disabled: true,
                height: 600,
            });

        return this.protocolTilePanel;
    },


    protocol: function() {
        var pkset = this.values.protocol;

        if(pkset) {
            var rest = Ext._create('edocs.protocolo.ProtocoloRestful');
            var mask = new Ext.LoadMask(Ext.getBody(), {msg: 'buscando documento...'});
            mask.show();
            rest.rendererProtocolReference(
                pkset,
                {
                    scope: this,
                    fn: function(document) {
                        this.getProtocolTilePanel().enable();
                        this.getProtocolTilePanel().setPageContent(document.content);
                    }
                },
                {
                    fn: function(message) {
                        Ext.Msg.show({
                            title: 'Buscando documento',
                            msg: message,
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK
                        });
                    }
                },
                {fn: function() {mask.hide();}}
            );

        }
        else {
            this.getProtocolTilePanel().disable();
            this.getProtocolTilePanel().setPageContent('');
        }
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.applyIf(cfg, {
            title: 'Referências do Protocolo'
        });

        Ext.apply(cfg, {
            width: 1000,
            items: [
                this.getFormPanel()
            ],
            buttons: [
                {
                    text: 'Fechar',
                    scope: this,
                    handler: function() { this.close(); }
                }
            ]
        });


        edocs.protocolo.ProtocolReferenceDetailWindow.superclass.constructor.call(this, cfg);
        this.protocol();
    }
});
